import AppKit

/// Lends the clipboard to Smart Paste and gives the user's contents back.
///
/// The transcript is written with the nspasteboard.org transient and
/// auto-generated markers, which clipboard-history apps skip, plus a private
/// marker naming this loan. The saved contents go back only while that marker
/// is still on the clipboard: if the user copied something meanwhile, or a
/// newer dictation took the clipboard, nothing is overwritten.
@MainActor
struct ClipboardKeeper {
    /// Every item on the clipboard, each as its representations in order.
    struct Snapshot: Equatable {
        struct Representation: Equatable {
            let type: NSPasteboard.PasteboardType
            let data: Data
        }

        let items: [[Representation]]
    }

    static let loanType = NSPasteboard.PasteboardType("com.audiowhisper.transcript-loan")
    static let transientType = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
    static let autoGeneratedType = NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType")

    var pasteboard: NSPasteboard = .general

    func save() -> Snapshot {
        Snapshot(items: (pasteboard.pasteboardItems ?? []).map { item in
            item.types.compactMap { type in
                item.data(forType: type).map { Snapshot.Representation(type: type, data: $0) }
            }
        })
    }

    /// Writes `text` as the clipboard's only contents, marked as this loan.
    func copy(_ text: String, loan: UUID) {
        pasteboard.declareTypes([.string, Self.loanType, Self.transientType, Self.autoGeneratedType], owner: nil)
        pasteboard.setString(text, forType: .string)
        pasteboard.setString(loan.uuidString, forType: Self.loanType)
        pasteboard.setData(Data(), forType: Self.transientType)
        pasteboard.setData(Data(), forType: Self.autoGeneratedType)
    }

    /// Puts `snapshot` back if the clipboard still holds this loan's text.
    @discardableResult
    func restore(_ snapshot: Snapshot, loan: UUID) -> Bool {
        guard pasteboard.string(forType: Self.loanType) == loan.uuidString else { return false }
        pasteboard.clearContents()
        let items = snapshot.items.filter { !$0.isEmpty }.map { representations in
            let item = NSPasteboardItem()
            for representation in representations { item.setData(representation.data, forType: representation.type) }
            return item
        }
        if !items.isEmpty { pasteboard.writeObjects(items) }
        return true
    }
}
